CREATE TABLE `gift` (
  `gid` varchar(36) COLLATE utf8mb4_general_ci NOT NULL COMMENT '礼物主键id',
  `uid` varchar(36) COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户表主键ID',
  `gname` varchar(36) COLLATE utf8mb4_general_ci NOT NULL COMMENT '礼物名',
  `gurl` varchar(255) COLLATE utf8mb4_general_ci NOT NULL COMMENT '礼物图片地址',
  `gneed` int unsigned NOT NULL DEFAULT '999999',
  `stocknum` int unsigned NOT NULL DEFAULT '0',
  `gct` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '礼物上架时间',
  `gstatus` enum('上架','下架') COLLATE utf8mb4_general_ci NOT NULL DEFAULT '上架' COMMENT '礼物的上架状态 1上架 0下架',
  PRIMARY KEY (`gid`),
  KEY `FK_Reference_11` (`uid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='用来存储礼品的信息';
