DROP TABLE IF EXISTS `orderinfo`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `orderinfo` (
  `orid` varchar(36) COLLATE utf8mb4_general_ci NOT NULL,
  `uid` varchar(36) COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户表主键ID',
  `gid` varchar(36) COLLATE utf8mb4_general_ci NOT NULL COMMENT '礼物主键id',
  `needor` varchar(36) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '999999' COMMENT '订单所需求积分表冗余方便查询',
  `address` varchar(255) COLLATE utf8mb4_general_ci NOT NULL COMMENT '收货地址',
  `remark` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '订单备注默认无',
  `orct` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '订单创建时间',
  `sendtime` date DEFAULT NULL COMMENT '发货时间',
  `signt` date DEFAULT NULL COMMENT '订单签收时间',
  `loginfo` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '物流信息单号',
  `orstatus` enum('待发货','已发货','已签收','已取消') COLLATE utf8mb4_general_ci NOT NULL DEFAULT '待发货' COMMENT '订单状态：0 - 待发货，1 - 已发货，2 - 已签收，3 - 已取消',
  PRIMARY KEY (`orid`,`uid`,`gid`),
  KEY `FK_Reference_7` (`uid`),
  KEY `FK_Reference_8` (`gid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='存储积分兑换礼品的订单信息';
/*!40101 SET character_set_client = @saved_cs_client */;

