/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `tri_order_before_insert_check` BEFORE INSERT ON `orderinfo` FOR EACH ROW BEGIN
    DECLARE stock INT;
    SELECT CAST(stocknum AS UNSIGNED) INTO stock FROM gift WHERE gid = NEW.gid;
    IF stock < 1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '礼品库存不足，无法兑换';
    END IF;
END */;;
