CREATE TABLE `pcatogory` (
  `pcid` varchar(36) COLLATE utf8mb4_general_ci NOT NULL COMMENT '摄影作品分类主键id',
  `pid` varchar(36) COLLATE utf8mb4_general_ci NOT NULL COMMENT '帖子的主键ID',
