--
-- Table structure for table `user`
--

DROP TABLE IF EXISTS `user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user` (
  `uid` varchar(36) COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户表主键ID',
  `uname` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '用户名',
  `pnum` varchar(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '手机号',
  `role` enum('管理员','普通用户') COLLATE utf8mb4_general_ci NOT NULL DEFAULT '普通用户' COMMENT '选择权限0-管理员 1普通用户',
  `pwd` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '头像地址',
  `vote` int unsigned NOT NULL DEFAULT '0',
  `uct` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '用户创建时间',
  `status` enum('正常','禁用') COLLATE utf8mb4_general_ci NOT NULL DEFAULT '正常' COMMENT '用户的状态',
  `openid` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `bio` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `vis_favorite` tinyint(1) NOT NULL DEFAULT '1' COMMENT '收藏是否对他人可见',
  `vis_like` tinyint(1) NOT NULL DEFAULT '1' COMMENT '喜欢是否对他人可见',
  `vis_following` tinyint(1) NOT NULL DEFAULT '1' COMMENT '关注列表是否对他人可见',
  `vis_followers` tinyint(1) NOT NULL DEFAULT '1' COMMENT '粉丝列表是否对他人可见',
  PRIMARY KEY (`uid`),
  UNIQUE KEY `uk_user_openid` (`openid`),
  UNIQUE KEY `uk_user_pnum` (`pnum`),
  KEY `AK_uni_username` (`uname`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='用来存储系统的用户的表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `user`
--

LOCK TABLES `user` WRITE;
/*!40000 ALTER TABLE `user` DISABLE KEYS */;
