/*!50003 DROP PROCEDURE IF EXISTS `proc_create_order` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `proc_create_order`(
    IN p_orid VARCHAR(36),
    IN p_uid VARCHAR(36),
    IN p_gid VARCHAR(36),
    IN p_address VARCHAR(255),
    IN p_remark VARCHAR(255),
    OUT p_result INT,
    OUT p_msg VARCHAR(255)
)
BEGIN
    DECLARE v_need_score INT;
    DECLARE v_user_score INT;
    DECLARE v_stock INT;
    DECLARE v_gift_exist INT;
    DECLARE v_user_exist INT;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SET p_result = 0;
        SET p_msg = '系统异常';
    END;

    START TRANSACTION;

    SELECT COUNT(*) INTO v_user_exist FROM user WHERE uid = p_uid;
    IF v_user_exist = 0 THEN
        SET p_result = 0;
        SET p_msg = '用户不存在';
        SELECT p_result, p_msg;
        ROLLBACK;
    END IF;

    SELECT COUNT(*) INTO v_gift_exist FROM gift WHERE gid = p_gid;
    IF v_gift_exist = 0 THEN
        SET p_result = 0;
        SET p_msg = '礼品不存在';
        SELECT p_result, p_msg;
        ROLLBACK;
    END IF;

    SELECT gneed INTO v_need_score FROM gift WHERE gid = p_gid;
    SELECT vote INTO v_user_score FROM user WHERE uid = p_uid;
    SELECT stocknum INTO v_stock FROM gift WHERE gid = p_gid;

    IF v_user_score < v_need_score THEN
        SET p_result = 0;
        SET p_msg = '积分不足';
        SELECT p_result, p_msg;
        ROLLBACK;
    END IF;

    IF v_stock < 1 THEN
        SET p_result = 0;
        SET p_msg = '库存不足';
        SELECT p_result, p_msg;
        ROLLBACK;
    END IF;

    INSERT INTO orderinfo(orid, uid, gid, needor, address, remark, signt)
    VALUES(p_orid, p_uid, p_gid, v_need_score, p_address, p_remark, CURDATE());

    UPDATE gift SET stocknum = stocknum - 1 WHERE gid = p_gid;
    UPDATE user SET vote = vote - v_need_score WHERE uid = p_uid;

    COMMIT;
    SET p_result = 1;
    SET p_msg = '订单创建成功';
    SELECT p_result, p_msg;
END ;;
DELIMITER ;
