DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `proc_user_login`(
    IN p_pnum VARCHAR(11),    -- 手机号
    IN p_pwd VARCHAR(64),    -- 密码
    OUT p_result INT         -- 1成功 0失败
)
BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SET p_result = 0;
    END;

    START TRANSACTION;
    IF EXISTS(SELECT 1 FROM user WHERE pnum = p_pnum AND pwd = p_pwd AND status = '正常') THEN
        SET p_result = 1;
    ELSE
        SET p_result = 0;
    END IF;
    COMMIT;
END ;;
DELIMITER ;
